INSERT INTO itu_zones.source (document) VALUES ('{"title": "ITU zones", "schema": "itu_zones", "owner": "International Amateur Radio Union (IARU), from the ITU''s CIRAF zones", "document_title": "IARU Region 1 HF Managers Handbook v8.2, chapter 9.8, \"Definition of ITU-Zones when used by radio amateurs\"", "document": "IARURegion1HFManagerHandbook8.2.1.pdf", "edition": "2000-11 (chapter 9.8 as printed in Handbook v8.2, 2016)", "url": "https://www.iaru-r1.org/wp-content/uploads/2019/12/IARURegion1HFManagerHandbook8.2.1.pdf", "authority": "IARU Region 1 recommendation REC/99/LH/C4.2 (Lillehammer 1999): ''when the ITU Zones are used for Amateur Radio purposes, the definition of the border-lines shall be included in the HF Managers Handbook''. Drafted by G3HTA from the ITU''s CIRAF broadcasting zones; approved by all three IARU regions (1999-2001).", "terms": "The handbook states no reproduction terms. This package does not redistribute it: it links to it, records its SHA-256, and holds the facts from chapter 9.8, credited to IARU Region 1.", "adif_version": "3.1.7", "published": {"IARURegion1HFManagerHandbook8.2.1.pdf": {"url": "https://www.iaru-r1.org/wp-content/uploads/2019/12/IARURegion1HFManagerHandbook8.2.1.pdf", "retrieved": "2026-10-06", "sha256": "8d64ab9bcfa6211392ebe299efd8a750d3f3ee889e63090b60ccee16a61ee33e"}}, "facts": ["itu_zones.json"], "derived_note": "derived/entity_zones.json (ours): ADIF DXCC entity -> ITU zones, built from the facts."}'::jsonb);
