INSERT INTO itu_zones.code VALUES ('itu_zones', 19, '19', NULL, NULL, NULL, NULL, NULL, 'IARURegion1HFManagerHandbook8.2.1.pdf, chapter 9.8, page 9.8-1, zone 19', '''50E'' is printed with the E as a superscript in both places (the text layer reads ''50 E'' for the first); transcribed ''50E''. UA9 between 60 and 80N west of 50E is the western Komi Republic, European Russia (54) - mapped by geography, judgement call.');
