INSERT INTO itu_zones.code VALUES ('itu_zones', 30, '30', NULL, NULL, NULL, NULL, NULL, 'IARURegion1HFManagerHandbook8.2.1.pdf, chapter 9.8, page 9.8-2, zone 30', '''EX (Kyrgyztan west of 75E)'' (spelling as published) boundary ''west of 75E''; ''EY (Tajikstan)'' spelling as published; ''EZ (Turkmenistan, UA4 (east of 50E)'' is published with the closing parenthesis after Turkmenistan missing - read as EZ (Turkmenistan), UA4 (east of 50E). UA9 south of 60N and west of 75E spans European Russia (Perm, southern Komi; 54) and Asiatic Russia (Sverdlovsk, Chelyabinsk, Kurgan, Tyumen, Omsk...; 15): dxcc left null.');
